module TopModule(input logic clk, input logic reset, input logic [3:0] req, output logic [3:0] grant);
  logic [3:0] state;
  always @(posedge clk) begin
    if (reset) state <= 4'b0001;
    else if (req == 4'b0000) state <= state;
    else if (req[state]) state <= state;
    else begin
      state <= req & (~req + 1'b1);
    end
  end
  assign grant = state & req;
endmodule

module TopModule(input logic clk, input logic reset, input logic [3:0] req, output logic [3:0] grant);
  logic [3:0] mask;
  always @(posedge clk) begin
    if (reset) begin
      mask <= 4'b1111;
    end else begin
      mask <= req & (~req + 1'b1);
    end
  end
  assign grant = req & mask;
endmodule

