module TopModule(input logic clk, input logic reset, input logic [3:0] req, output logic [3:0] grant);
  logic [3:0] selected;
  always @(posedge clk) begin
    if (reset) selected <= 4'b0001;
    else if (req != 0) selected <= req & (~req + 1'b1);
  end
  assign grant = req & selected;
endmodule

module TopModule(input logic clk, input logic reset, input logic [3:0] req, output logic [3:0] grant);
  logic [3:0] chosen;
  always @(posedge clk) begin
    if (reset) chosen <= 4'b0001;
    else casez (req)
      4'b1???: chosen <= 4'b1000;
      4'b01??: chosen <= 4'b0100;
      4'b001?: chosen <= 4'b0010;
      4'b0001: chosen <= 4'b0001;
      default: chosen <= chosen;
    endcase
  end
  assign grant = req & chosen;
endmodule

module TopModule(input logic clk, input logic reset, input logic [3:0] req, output logic [3:0] grant);
  logic [3:0] hot;
  always @(posedge clk) begin
    if (reset) hot <= 4'b0001;
    else if (req[3]) hot <= 4'b1000;
    else if (req[2]) hot <= 4'b0100;
    else if (req[1]) hot <= 4'b0010;
    else if (req[0]) hot <= 4'b0001;
  end
  assign grant = req & hot;
endmodule

module TopModule(input logic clk, input logic reset, input logic [3:0] req, output logic [3:0] grant);
  always @(posedge clk begin
    grant <= req;
  end
endmodule
